            # XXX: pretty sure this is horrible after so many aliases
            while rgb[color] < factor:
                nc = min(256 - rgb[color], 256)
                rgb[color] += nc
                nn += 1
                if nn > 2:
                    nn = 0
                rgb[nn] = nc
            db["rgb_color"] = rgb

        trans_ids = {}
